  class GitManager { private string $projectRoot; public function __construct(?string $projectRoot = null) { $this->projectRoot = $projectRoot ?? __DIR__ . '/../../../../'; } public function getCurrentBranch(): string { $branch = shell_exec("git -C {$this->projectRoot} rev-parse --abbrev-ref HEAD 2>/dev/null"); return trim($branch ?: 'master'); } public function getCurrentCommit(): string { $commit = shell_exec("git -C {$this->projectRoot} rev-parse --short HEAD 2>/dev/null"); return trim($commit ?: 'head'); } public function isWorkingTreeClean(): bool { $status = shell_exec("git -C {$this->projectRoot} status --porcelain 2>/dev/null"); return empty(trim($status ?: '')); } public function getChangedFiles(): array { $output = shell_exec("git -C {$this->projectRoot} diff --name-only HEAD 2>/dev/null"); if (!$output) { $output = shell_exec("git -C {$this->projectRoot} status --porcelain 2>/dev/null"); if ($output) { $lines = explode("\n", trim($output)); $files = []; foreach ($lines as $l) { if (trim($l)) { $files[] = trim(substr($l, 3)); } } return array_unique($files); } return []; } $lines = explode("\n", trim($output)); return array_values(array_filter(array_map('trim', $lines))); } public function getRecentCommits(int $count = 10): array { $output = shell_exec("git -C {$this->projectRoot} log -n {$count} --oneline 2>/dev/null"); if (!$output) return []; return array_values(array_filter(array_map('trim', explode("\n", $output)))); } } 